  const RUNTIME_BEHAVIORS = {
    stored: {
      label: "Stored value",
      symbol: "●",
      shape: "circle"
    },
    startup: {
      label: "Read on startup",
      symbol: "▶",
      shape: "triangle"
    },
    saved: {
      label: "React when settings are saved",
      symbol: "■",
      shape: "square"
    },
    "startup-saved": {
      label: "Startup and saved reaction",
      symbol: "◆",
      shape: "diamond"
    }
  };

  function runtimeBehaviorIncludesStartup(
    reaction
  ) {
    return (
      reaction === "startup" ||
      reaction === "startup-saved"
    );
  }

  function runtimeBehaviorIncludesSaved(
    reaction
  ) {
    return (
      reaction === "saved" ||
      reaction === "startup-saved"
    );
  }

  function runtimeBehaviorEmitsImpulse(
    reaction
  ) {
    return (
      runtimeBehaviorIncludesStartup(
        reaction
      ) ||
      runtimeBehaviorIncludesSaved(
        reaction
      )
    );
  }

  const port = (
    id,
    label,
    type,
    extra = {}
  ) => ({
    id,
    label,
    type,
    ...extra
  });

  const genericPort = (
    id,
    label,
    typeVar,
    constraint = "value",
    extra = {}
  ) => ({
    id,
    label,
    typeVar,
    constraint,
    ...extra
  });

  function apiCompositeProxyPort(
    boundary,
    index = 0
  ) {
    const id = String(
      boundary?.id ||
      `proxy-${index + 1}`
    );
    const label = String(
      boundary?.label ||
      boundary?.internalPortId ||
      `Port ${index + 1}`
    ).slice(0, 160);
    const type = String(
      boundary?.type || ""
    ).trim();
    const typeVar = String(
      boundary?.typeVar || ""
    ).trim();
    const constraint = String(
      boundary?.constraint || "value"
    ).trim();
    const extra = {
      detail:
        `API Composite boundary · ${String(boundary?.internalNodeId || "node")}.${String(boundary?.internalPortId || "port")}`,
      apiCompositeProxy: true,
      internalNodeId:
        String(boundary?.internalNodeId || ""),
      internalPortId:
        String(boundary?.internalPortId || "")
    };

    return type
      ? port(id, label, type, extra)
      : genericPort(
          id,
          label,
          typeVar || `C${index + 1}`,
          constraint,
          extra
        );
  }

  function apiCompositeInternalDefinitionAllowed(
    definition
  ) {
    if (!definition) return false;
    if (
      definition.catalogGenerated === true ||
      definition.unavailableApiContract === true
    ) {
      return true;
    }
    if (
      definition.apiCompositeContainer === true ||
      definition.customCSharpNode === true ||
      definition.customCSharpSyntaxNode === true ||
      definition.customCSharpSubgraphOnly === true ||
      definition.customCSharpCatalogNode === true
    ) {
      return false;
    }
    const group = String(
      definition.group || ""
    );
    return Boolean(
      group &&
      ![
        "Lifecycle",
        "Packed Configuration",
        "Project"
      ].includes(group)
    );
  }

  function apiCompositeStoredNodeSupported(
    node
  ) {
    if (
      node?.kind !== "operator" ||
      node.operatorId ===
        "container.apiComposite"
    ) {
      return false;
    }
    const definition =
      OPERATOR_DEFINITIONS[
        node.operatorId
      ];
    const contract =
      node.apiContract ||
      definition?.preservedApiContract;
    if (
      definition?.catalogGenerated === true ||
      definition?.unavailableApiContract === true ||
      contract
    ) {
      return Boolean(
        String(
          contract?.ownerType || ""
        ).trim() &&
        String(contract?.kind || "")
          .trim()
      );
    }
    return apiCompositeInternalDefinitionAllowed(
      definition
    );
  }

